output_text:
[
  {
    "id": "take_entry_cart",
    "text": "The customer is obliged to check out the entry cart before continuing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_available": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "acquire_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "acquire_entry_cart"
    }
  },
  {
    "id": "no_hand_shopping",
    "text": "Items should not be carried by hand; item pickup is permitted only while the customer has the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "cart_in_possession": "hasCart"
      },
      "events": {
        "hand_pickup_attempt": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "cart_in_possession"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "hand_pickup_attempt"
        ]
      }
    }
  },
  {
    "id": "cart_assisted_items_return_cart",
    "text": "After any cart-assisted pickup from a product bay, the cart must eventually be returned to the designated cart-return cell.",
    "abstraction": {
      "state_properties": {
        "apple_bay": {
          "or": [
            "at(1,3)",
            "at(2,2)",
            "at(2,4)"
          ]
        },
        "bread_bay": {
          "or": [
            "at(3,2)",
            "at(3,4)"
          ]
        },
        "milk_bay": {
          "or": [
            "at(5,2)",
            "at(5,4)"
          ]
        },
        "egg_bay": {
          "or": [
            "at(6,2)",
            "at(6,4)"
          ]
        },
        "product_bay": {
          "or": [
            "apple_bay",
            "bread_bay",
            "milk_bay",
            "egg_bay"
          ]
        },
        "cart_return_cell": "at(0,1)"
      },
      "events": {
        "cart_assisted_product_pickup": {
          "pre": {
            "and": [
              "product_bay",
              "hasCart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "return_cart": {
          "pre": {
            "and": [
              "cart_return_cell",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_assisted_product_pickup",
      "discharge": "return_cart"
    }
  },
  {
    "id": "no_east_from_egg_bay_with_cart",
    "text": "The far egg shelf may be approached from either aisle, but a customer pushing a cart must not continue east from that far shelf bay.",
    "abstraction": {
      "state_properties": {
        "upper_egg_approach": "at(6,2)",
        "lower_egg_approach": "at(6,4)",
        "egg_bay": {
          "or": [
            "upper_egg_approach",
            "lower_egg_approach"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "egg_bay",
          "pushing_cart",
          "E"
        ]
      }
    }
  },
  {
    "id": "leave_cart_only_at_return",
    "text": "A cart may be left behind only at the designated return cell near the west side of the store.",
    "abstraction": {
      "state_properties": {
        "designated_cart_return": "at(0,1)"
      },
      "events": {
        "leave_cart_outside_return": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "designated_cart_return"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return"
    }
  },
  {
    "id": "cart_parked_before_exit",
    "text": "Before leaving the store, the entry cart must be parked at the cart-return cell.",
    "abstraction": {
      "state_properties": {
        "cart_return_cell": "at(0,1)",
        "cart_parked_at_return": "cartAt(0,1)"
      },
      "events": {
        "park_cart_at_return": {
          "pre": {
            "and": [
              "cart_return_cell",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "park_cart_at_return"
    }
  },
  {
    "id": "pedestrian_only_exit_side",
    "text": "The checkout and exit side of the supermarket is pedestrian-only, so customers must not push carts there.",
    "abstraction": {
      "state_properties": {
        "exit_side": {
          "or": [
            "at(7,0)",
            "at(8,0)",
            "at(9,0)",
            "at(7,1)",
            "at(8,1)",
            "at(9,1)",
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_side",
          "pushing_cart"
        ]
      }
    }
  },
  {
    "id": "do_not_reclaim_returned_cart",
    "text": "Once the cart has been returned to the return cell, it should not be picked up again.",
    "abstraction": {
      "state_properties": {
        "returned_cart_available": "cartAt(0,1)"
      },
      "events": {
        "reclaim_returned_cart": {
          "pre": {
            "and": [
              "returned_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "reclaim_returned_cart"
    }
  }
]
